    'category_copy' => [
        'Draped Bust Half Cent' => ['copy' => 'Struck over 200 years ago, this scarce copper half cent bears Robert Scot\'s classic Draped Bust design. The obverse shows Liberty with a ribbon in her flowing hair and a plunging neckline draped with linen. The reverse bears UNITED STATES OF AMERICA and the fraction 1/200 beneath a laurel wreath and HALF CENT.',
            'alt1' => '', 'alt2' => ''],
        'Classic Head Half Cent' => ['copy' => 'Struck over 180 years ago, this scarce copper half cent bears John Reich\'s Classic Head design. The obverse depicts Liberty with curly hair held by a band inscribed LIBERTY. The reverse bears HALF CENT surrounded by a laurel wreath and UNITED STATES OF AMERICA.',
            'alt1' => '', 'alt2' => ''],
        'Braided Hair Half Cent' => ['copy' => 'This scarce copper Braided Hair half cent was struck over 150 years ago. It bears Christian Gobrecht\'s classic design. The obverse depicts Liberty wearing a diadem, her long hair in a bun held by beaded cords. The reverse shows HALF CENTS surrounded by a wreath and UNITED STATES OF AMERICA.',
            'alt1' => '', 'alt2' => ''],
        'Draped Bust Large Cent' => ['copy' => 'Struck over 200 years ago, this copper Draped Bust large cent is 50% larger than today\'s cents. Its classic obverse by Robert Scot depicts Liberty with a plunging neckline and flowing hair held by a ribbon. The reverse shows ONE CENT, surrounded by a wreath, UNITED STATES OF AMERICA and the fraction 1/100.',
            'alt1' => '', 'alt2' => ''],
        'Classic Head Large Cent' => ['copy' => 'Struck over 200 years ago, this copper Classic Head large cent is 50% larger than today\'s cents. Its classic obverse by John Reich depicts 13 stars around Liberty, her curly hair held by a band inscribed LIBERTY. The reverse bears ONE CENT inside a laurel wreath and UNITED STATES OF AMERICA.',
            'alt1' => '', 'alt2' => ''],
        'Coronet Head Large Cent' => ['copy' => 'Struck over 180 years ago, this copper Coronet Head large cent - also called the Matron Head large cent - is 50% larger than today\'s cents. It depicts a more serious Liberty, with a diadem inscribed LIBERTY and long hair in a bun held by plain cords. The reverse shows ONE CENT surrounded by a laurel wreath and UNITED STATES OF AMERICA.',
            'alt1' => '', 'alt2' => ''],
        'Braided Hair Large Cent' => ['copy' => 'Struck over 150 years ago, this copper Braided Hair large cent bears Christian Gobrecht\'s classic design. Its obverse depicts Liberty in a diadem, her long tresses held in a bun held by two beaded cords. The reverse bears ONE CENT encircled by a wreath and UNITED STATES OF AMERICA.',
            'alt1' => '', 'alt2' => ''],
        'Flying Eagle Small Cent' => ['copy' => 'Briefly minted from 1856-1858, Flying Eagle cents were America\'s first small-size 1c coins. Struck in 88% copper and 12% nickel, these coins feature an eagle in flight on the obverse and a wreath of corn, wheat, cotton and tobacco on the reverse.',
            'alt1' => '', 'alt2' => ''],
        'Indian Head Small Cent' => ['copy' => 'Struck from 1859-1864, copper-nickel Indian Head cents depict Liberty with an Indian headdress and not an actual Native American. The reverse of first-year coins featured a laurel wreath, which changed in 1860 to an oak wreath and small shield.',
            'alt1' => 'The composition of Indian Head cents was changed to bronze during 1864, and a slightly sharper Indian Head portrait was created near the end of 1864 that included designer James B. Longacre\'s initial L on the lower ribbon behind the neck.', 'alt2' => ''],
        'Lincoln Wheat Small Cent' => ['copy' => 'Lincoln cents with the original Wheat Ears reverse were introduced in 1909 on the 100th anniversary of Abraham Lincoln\'s birth and were struck until 1958. These bronze cents were the first circulating U.S. coins to depict an actual person.',
            'alt1' => 'In 1943, the U.S. Mint struck Lincoln cents in zinc-coated steel to save copper for munitions and other military materials in World War II. Each unique one-year-only issue bears Victor D. Brenner\'s Lincoln portrait obverse and Wheat Ears reverse designs.', 'alt2' => ''],
        'Lincoln Memorial Small Cent' => ['copy' => 'The Lincoln cent was redesigned in 1959 to celebrate the 150th anniversary of Abraham Lincoln\'s birth. The obverse continued to depict Lincoln\'s portrait, while Frank Gasparro\'s new reverse depicted the Lincoln Memorial.',
            'alt1' => '', 'alt2' => ''],
        'Lincoln Bicentennial Small Cent' => ['copy' => 'In honor of the bicentennial of Abraham Lincoln\'s birth and the 100th anniversary of the Lincoln cent, this special one-year-only cent bears a special reverse design depicting the first of four major stages in Abraham Lincoln\'s life.',
            'alt1' => 'In honor of the bicentennial of Abraham Lincoln\'s birth and the 100th anniversary of the Lincoln cent, this special one-year-only cent bears a special reverse design depicting the second of four major stages in Abraham Lincoln\'s life.', 'alt2' => 'In honor of the bicentennial of Abraham Lincoln\'s birth and the 100th anniversary of the Lincoln cent, this special one-year-only cent bears a special reverse design depicting the third of four major stages in Abraham Lincoln\'s life.'],
        'Lincoln Shield Small Cent' => ['copy' => 'Lincoln cents issued 2010-date bear a new reverse by Lyndall Bass, which depicts a "Union Shield" to represent President Lincoln\'s preservation of the United States as a single, unified nation. The obverse bears Victor D. Brenner\'s original portrait design.',
            'alt1' => '', 'alt2' => ''],
        'Two Cent' => ['copy' => 'This century-old bronze two-cent piece is from the first U.S. coin series to bear IN GOD WE TRUST. The motto appears on the obverse, on a ribbon above the Union Shield. Behind the shield are two crossed arrows and an encircling wreath. The reverse bears 2 CENTS surrounded by two sheaves of wheat tied by a ribbon and UNITED STATES OF AMERICA.',
            'alt1' => '', 'alt2' => ''],
        'Three Cent Silver' => ['copy' => 'This century-old silver three-cent piece (or "Trime") is the smallest-denomination silver coin ever issued by the U.S. Mint. Its obverse depicts a Union Shield atop a six-pointed star. UNITED STATES OF AMERICA and the date encircle the design. The reverse features the Roman numeral III surrounded by a large, stylized letter C and 13 stars.',
            'alt1' => '', 'alt2' => ''],
        'Three Cent Nickel' => ['copy' => 'Struck over 130 years ago, this nickel three-cent piece bears James B. Longacre\'s classic design. It depicts Liberty in a diadem inscribed LIBERTY, her long hair in an intricate braid. The reverse bears the Roman numeral III inside by a laurel wreath.',
            'alt1' => '', 'alt2' => ''],
        'Flowing Hair Half Dime' => ['copy' => 'Struck over 200 years ago, this silver Flowing Hair half dime is one of America\'s oldest federal-issue coins. Its obverse bears Robert Scot\'s classic image of Liberty with long hair flowing to her shoulders. Surrounding her are 13 stars, with the date below. The reverse depicts an American eagle encircled by a laurel wreath and UNITED STATES OF AMERICA.',
            'alt1' => '', 'alt2' => ''],
        'Capped Bust Half Dime' => ['copy' => 'Struck over 180 years ago, this silver Capped Bust half dime bears John Reich\'s classic design. It depicts 13 stars around Liberty in a cloth cap, her curly hair reaching her shoulder where a brooch secures her gown. The reverse bears UNITED STATES OF AMERICA around an American eagle with Union Shield holding an olive branch and three arrows. The denomination 5 c. is below the eagle, with E PLURIBUS UNUM on a banner above.',
            'alt1' => '', 'alt2' => ''],
        'Seated Half Dime' => ['copy' => 'This century-old, 90% silver Liberty Seated half dime is from the final series before the denomination was retired. Its obverse depicts Liberty seated on a rock holding a Union Shield and a Liberty cap atop a pole. The reverse bears HALF DIME surrounded by a laurel wreath and UNITED STATES OF AMERICA.',
            'alt1' => '', 'alt2' => ''],
        'Shield Nickel' => ['copy' => 'The classic Shield nickel of 1866-1883 replaced the silver half dimes of 1794-1873. The coin\'s obverse depicts a shield and wreath, while the reverse features a large numeral "5" inside a circle of 13 stars above the word CENTS.',
            'alt1' => '', 'alt2' => ''],
        'Liberty Nickel' => ['copy' => 'When first issued in 1883, Liberty Head Nickels (or "V" nickels) bore just a large Roman numeral "V" for the denomination. So the Mint soon added the word CENTS to stop con artists from gold plating them and passing them off as $5 gold pieces.',
            'alt1' => '', 'alt2' => ''],
        'Buffalo Nickel' => ['copy' => 'Also called the Indian Head nickel, the prized Buffalo nickel is considered the most uniquely American coin. Designed by sculptor James E. Fraser, the obverse depicts a proud Native American. The distinctive reverse features an American bison.',
            'alt1' => '', 'alt2' => ''],
        'Jefferson Nickel' => ['copy' => 'The Jefferson nickel offers collectors an affordable way to build a complete collection. The obverse bears a striking portrait of America\'s founding father and 3rd president, while the reverse depicts his home, Monticello.',
            'alt1' => 'Unlike traditional Jefferson nickels, this historic coin was struck in a special alloy of 35% silver to save nickel for the World War II effort. Like all silver wartime nickels, it bears a larger mint mark on the reverse above Monticello\'s dome.', 'alt2' => 'This coin is the first of four issues in the Westward Journey nickel series honoring the bicentennial of the Louisiana Purchase and the Lewis & Clark expedition. Its one-year-only design bears a special reverse adapted from the Indian Peace medals carried by Lewis and Clark.'],
        'Draped Bust Dime' => ['copy' => 'Struck over 200 years ago, this classic Draped Bust silver dime designed by Robert Scot depicts Liberty with a plunging neckline and a ribbon in her flowing hair. 13 stars surround her, with LIBERTY above and the date below. The reverse bears a large heraldic eagle patterned after the Great Seal of the United States.',
            'alt1' => '', 'alt2' => ''],
        'Capped Bust Dime' => ['copy' => 'Designed by John Reich, this classic silver dime depicts Liberty on the obverse with hair beneath a cloth cap surrounded by 13 stars. Its reverse features the denomination 10 c. beneath an eagle with shield on a branch holding three arrows.',
            'alt1' => '', 'alt2' => ''],
        'Seated Liberty Dime' => ['copy' => 'Designed by Christian Gobrecht, this 90% silver dime depicts Liberty seated on a rock, holding a shield in her right hand and a Liberty cap on a pole in her left. The reverse displays a wreath, the denomination and UNITED STATES OF AMERICA.',
            'alt1' => '', 'alt2' => ''],
        'Barber Dime' => ['copy' => 'Known as the Barber dime after its designer, this classic Liberty Head dime was struck in 90% silver. Its obverse depicts Liberty facing right wearing a Phrygian cap and laurel wreath, while the reverse shows a wreath and the denomination ONE DIME.',
            'alt1' => '', 'alt2' => ''],
        'Mercury Dime' => ['copy' => 'This 90% silver Mercury dime was designed by A.A. Weinman, who also created the Liberty Walking half dollars of 1916-1947. Its obverse features Liberty in a winged cap to symbolize freedom of thought. The reverse depicts a fasces against a branch in the background.',
            'alt1' => '', 'alt2' => ''],
        'Roosevelt Dime' => ['copy' => 'This dime honors America\'s 32nd and only four-term president, Franklin D. Roosevelt, Designed by John R. Sinnock, the obverse depicts Roosevelt\'s portrait. The reverse shows a torch between olive and oak branches, symbolizing peace, strength and independence.',
            'alt1' => '', 'alt2' => ''],
        'Twenty Cent' => ['copy' => 'The Liberty Seated twenty-cent piece was the shortest-lived U.S. coin denomination. This century-old, 90% silver coin depicts 13 stars around Liberty, who sits on a rock with a Union Shield and a Liberty cap on a pole. The reverse shows an eagle with an olive branch and three arrows. Encircling the reverse are UNITED STATES OF AMERICA and TWENTY CENTS.',
            'alt1' => '', 'alt2' => ''],
        'Draped Bust Quarter' => ['copy' => 'Struck over 200 years ago, this silver Draped Bust quarter bears Robert Scot\'s classic designs. The obverse shows 13 stars around Liberty with a plunging neckline, her long hair held by a ribbon. The reverse is the second design to appear on a U.S. quarter. It bears a heraldic eagle surrounded by UNITED STATES OF AMERICA and the denomination 20 c.',
            'alt1' => '', 'alt2' => ''],
        'Capped Bust Quarter' => ['copy' => 'Struck around 200 years ago, this silver Capped Bust quarter bears John Reich\'s classic Capped Bust design. It depicts Liberty in a cloth cap, surrounded by 13 stars and the date of issue. The reverse shows a banner with the motto E PLURIBUS UNUM above an eagle with Union Shield, an olive branch and three arrows. Encircling the eagle are 25 c. and UNITED STATES OF AMERICA.',
            'alt1' => 'Struck over 180 years ago, this Capped Bust silver quarter bears John Reich\'s Capped Bust design, which William Kneass modified. It depicts Liberty in a cloth cap, surrounded by 13 stars and the date of issue. The reverse shows an American eagle with Union Shield, an olive branch and three arrows. Encircling the eagle are 25 c. and UNITED STATES OF AMERICA.', 'alt2' => ''],
        'Seated Liberty Quarter' => ['copy' => 'Designed by Christian Gobrecht, this classic 90% silver quarter features Liberty seated on a rock surrounded by 13 stars. Her left hand holds a liberty cap atop a pole; her right, a shield inscribed LIBERTY. The reverse depicts an eagle on an olive branch holding three arrows.',
            'alt1' => '', 'alt2' => ''],
        'Barber Quarter' => ['copy' => 'Designed by Charles E. Barber, this 90% silver Liberty Head quarter (or Barber quarter) depicts Liberty wearing a laurel wreath and Phrygian cap with a band inscribed LIBERTY. The reverse bears an adaptation of the Great Seal of the United States.',
            'alt1' => '', 'alt2' => ''],
        'Standing Liberty Quarter' => ['copy' => 'Considered one of America\'s most beautiful coinage designs, this Standing Liberty quarter depicts Liberty standing in a gateway, holding an olive branch and uncovering a shield. The reverse features 13 stars surrounding a majestic eagle in flight.',
            'alt1' => '', 'alt2' => ''],
        'Washington Quarter' => ['copy' => 'The obverse of this Washington quarter bears John Flanagan\'s familiar portrait of America\'s first president. Its reverse features his depiction of a proud eagle with spread wings, perched on a bundle of arrows above two olive branches.',
            'alt1' => 'This Bicentennial quarter celebrates the 200th anniversary of America\'s founding with a special reverse by Jack L. Ahr, which depicts a military drummer and a victory torch encircled by 13 stars. The obverse bears John Flanagan\'s original design with dual date 1776-1976.', 'alt2' => ''],
        'State Quarter' => ['copy' => 'The Statehood quarters of 1999-2008 honored the 50 states in order of statehood, with reverse designs representing the featured state. John Flanagan\'s original Washington portrait obverse was slightly modified to make room for the new, changing reverse designs.',
            'alt1' => '', 'alt2' => ''],
        'DC & US Territories Quarter' => ['copy' => 'In 2009, the U.S. Mint followed its Statehood quarter program with six new quarters bearing reverse designs honoring the District of Columbia and the five U.S. territories. Each bore John Flanagan\'s modified Washington portrait obverse.',
            'alt1' => '', 'alt2' => ''],
        'America the Beautiful Quarter' => ['copy' => 'The National Park quarters series honors a national park or historic site in each of the 50 states, the District of Columbia and the five U.S. territories. Each coin bears John Flanagan\'s modified Washington portrait obverse and a special reverse design representing the featured site.',
            'alt1' => '', 'alt2' => ''],
        'Capped Bust Half Dollar' => ['copy' => 'Struck over 180 years ago, this 89% silver Capped Bust half dollar bears John Reich\'s classic design. It depicts Liberty with long, curling hair and a cloth cap, surrounded by 13 stars and the date. The reverse shows an American eagle with Union Shield, an olive branch and three arrows. A banner above the eagle reads E PLURIBUS UNUM, with 50 c. below and UNITED STATES OF AMERICA surrounding. Inscribed along the coin\'s edge is FIFTY CENTS or HALF A DOLLAR.',
            'alt1' => 'This 90% silver Capped Bust half dollar was struck over 180 years ago. Its obverse depicts 13 stars around Liberty, who wears long hair and a cloth cap. The reverse shows an American eagle with shield, olive branch and three arrows. Surrounding the eagle are the denomination and UNITED STATES OF AMERICA.', 'alt2' => ''],
        'Seated Liberty Half Dollar' => ['copy' => 'This 90% silver Liberty Seated half dollar was struck over a century ago. Its classic obverse shows Liberty seated on a rock, holding a Union Shield, a ribbon inscribed LIBERTY and a Liberty cap atop a pole. 13 stars and the date surround her. The reverse depicts an American eagle with Union Shield, an olive branch and three arrows. Encircling the reverse are UNITED STATES OF AMERICA and HALF DOLLAR.',
            'alt1' => '', 'alt2' => ''],
        'Barber Half Dollar' => ['copy' => 'This 90% silver Liberty Head half dollar (or Barber half dollar) bears Charles E. Barber\'s classic depiction of Liberty wearing a laurel wreath and Phrygian cap held by a band inscribed LIBERTY. The reverse bears an adaptation of the Great Seal of the United States.',
            'alt1' => '', 'alt2' => ''],
        'Liberty Walking Half Dollar' => ['copy' => 'Designed by Adolph A. Weinman, this 90% silver Liberty Walking half dollar is one of America\'s most beautiful coins. The obverse shows Liberty with arm outstretched, striding towards the dawn of a new day. The reverse depicts an eagle on a rocky crag, where a pine branch grows to symbolize strength.',
            'alt1' => '', 'alt2' => ''],
        'Franklin Half Dollar' => ['copy' => 'This Franklin half dollar is from America\'s last circulating half dollar series struck entirely in 90% silver. Its obverse bears John R. Sinnock\'s portrait of Benjamin Franklin, while the reverse depicts the Liberty Bell and a small eagle.',
            'alt1' => '', 'alt2' => ''],
        'Kennedy Half Dollar' => ['copy' => 'This Kennedy half dollar honors America\'s 35th president, John F. Kennedy. The obverse designed by Gilroy Roberts features a left-facing portrait of Kennedy, while Frank Gasparro\'s reverse displays the presidential coat of arms.',
            'alt1' => 'This Bicentennial half dollar honors the 200th anniversary of America\'s founding with Seth Huntington\'s reverse featuring Independence Hall and the inscription 200 YEARS OF FREEDOM. The obverse by Gilroy Roberts depicts 35th President John F. Kennedy and the dual date 1776-1976.', 'alt2' => ''],
        'Draped Bust Dollar' => ['copy' => '',
            'alt1' => 'This Draped Bust silver dollar was struck over 200 years ago. Its classic obverse by Robert Scot depicts 13 stars around Liberty with a plunging neckline and a ribbon in her long hair. Scot\'s reverse bears a stunning heraldic eagle adapted from the Great Seal of the United States.', 'alt2' => ''],
        'Seated Liberty Dollar' => ['copy' => 'This century-old 90% silver Liberty Seated dollar bears Christian Gobrecht\'s classic design. On the obverse, Liberty sits on a rock surrounded by 13 stars. She holds a Union Shield with banner that reads LIBERTY and a Liberty cap atop a pole. The reverse bears an American eagle with shield, olive branch and 3 arrows. Encircling the eagle are the denomination ONE DOL. and UNITED STATES OF AMERICA.',
            'alt1' => '', 'alt2' => ''],
        'Trade Dollar' => ['copy' => 'Designed by William Barber, this 90% silver Trade dollar was struck over a century ago for use in trade with Asia. Its obverse depicts 13 stars around Liberty, who sits on a bale of merchandise by the sea. Her right hand extends an olive branch; her left rests atop a sheaf of wheat and a ribbon inscribed LIBERTY. The reverse shows an American eagle holding three arrows and an olive branch. Below the eagle is 420 GRAINS, 900 FINE., while a banner above reads E PLURIBUS UNUM. UNITED STATES OF AMERICA and TRADE DOLLAR encircle the reverse.',
            'alt1' => '', 'alt2' => ''],
        'Morgan Dollar' => ['copy' => 'This large 90% silver Morgan dollar bears George T. Morgan\'s classic depiction of Liberty facing left in a Phrygian cap and a spray of leaves held by a ribbon inscribed LIBERTY. The reverse features an eagle clutching a branch and three arrows.',
            'alt1' => '', 'alt2' => ''],
        'Morgan Dollar Toned' => ['copy' => 'This large 90% silver Morgan dollar bears George T. Morgan\'s classic depiction of Liberty facing left in a Phrygian cap and a spray of leaves held by a ribbon inscribed LIBERTY. The reverse features an eagle clutching a branch and three arrows.',
            'alt1' => '', 'alt2' => ''],
        'Peace Dollar' => ['copy' => 'Designed by Anthony de Francisci, this 90% silver Peace depicts a left-facing Liberty wearing a diadem of spikes. The reverse shows an eagle perched on a rock with a laurel branch above the word PEACE, facing the rays of a rising sun.',
            'alt1' => '', 'alt2' => ''],
        'Eisenhower Dollar' => ['copy' => 'This large dollar coin depicts 34th President Dwight D. Eisenhower, with LIBERTY above and the date below. Next to the portrait is the motto IN GOD WE TRUST. Adapted from the Apollo 11 mission patch, the reverse shows an eagle landing on the moon\'s surface, with the earth and E PLURIBUS UNUM above. Encircling the design are UNITED STATES OF AMERICA and ONE DOLLAR.',
            'alt1' => 'This special Bicentennial dollar was struck to celebrate the 200th anniversary of America\'s founding. Its obverse depicts 34th President Dwight D. Eisenhower and the dual date 1776-1976. On the reverse, the Liberty Bell is superimposed over the moon, with E PLURIBUS UNUM to the right. UNITED STATES OF AMERICA and ONE DOLLAR encircle the reverse.', 'alt2' => ''],
        'Susan B Anthony Dollar' => ['copy' => 'This historic coin is from the America\'s first small-size dollar series. Its obverse depicts women\'s rights pioneer Susan B. Anthony. Surrounding her portrait are by 13 stars, LIBERTY, IN GOD WE TRUST and the date. Adapted from the Apollo 11 mission patch, the reverse shows an eagle landing on the moon with the earth in the background. Above the eagle are UNITED STATES OF AMERICA and E PLURIBUS UNUM, with ONE DOLLAR below.',
            'alt1' => '', 'alt2' => ''],
        'Native American Dollar' => ['copy' => 'This historic Sacagawea dollar honors Lewis and Clark\'s young Shoshone guide. The obverse depicts Sacagawea holding her infant son, Jean Baptiste. LIBERTY is inscribed above the pair, with IN GOD WE TRUST on the left and the date at right. The reverse bears a soaring American eagle and E PLURIBUS UNUM. Encircling the reverse are 13 stars, UNITED STATES OF AMERICA and ONE DOLLAR.',
            'alt1' => 'This historic Native American dollar is from America\'s third "golden dollar" series. Its obverse depicts Lewis & Clark\'s guide Sacagawea and her infant son, Jean Baptiste. The one-year-only reverse honors Native Americans and their contributions. Inscribed along the edge are the date of issue, mint mark and E PLURIBUS UNUM.', 'alt2' => ''],
        'Presidential Dollar' => ['copy' => 'Presidential dollars honor America\'s presidents in order of service. Each obverse depicts the featured president, while a common reverse shows the Statue of Liberty and the denomination $1. Edge inscriptions bear each coin\'s date, mint mark and the mottoes IN GOD WE TRUST and E PLURIBUS UNUM.',
            'alt1' => 'Presidential dollars honor America\'s presidents in order of service. Each obverse depicts the featured president, while the reverse shows the Statue of Liberty and the denomination $1. Edge inscriptions bear each coin\'s date, mint mark and the motto E PLURIBUS UNUM.', 'alt2' => ''],
        'Gold $2.50 Quarter Eagle' => ['copy' => 'This gold Classic Head quarter eagle was designed by William Kneass. Its obverse is based on John Reich\'s classic image of Liberty with flowing hair held by a band inscribed LIBERTY. The date is below, with 13 stars surrounding. The reverse depicts UNITED STATES OF AMERICA and 2 1/2 D. around an American eagle with Union shield, olive branch and three arrows.',
            'alt1' => 'This gold Liberty Head quarter eagle - also called a Coronet Head or Braided Hair quarter eagle - bears Christian Gobrecht\'s classic designs. The obverse depicts 13 stars around Liberty, who wears a diadem inscribed LIBERTY. A string of beads holds her hair up in a bun. The reverse shows an American eagle with Union Shield, oak branch and three arrows. Encircling the design are united STATES OF AMERICA and 2 1/2 D.', 'alt2' => 'This gold Indian Head quarter eagle is one of America\'s most unique coins. Designed by Bela Lyon Pratt, the designs are sunken into the surface. The obverse depicts a Native American chief surrounded by 13 stars, with LIBERTY above and the date below. The reverse shows an eagle with olive branch perched on a bundle of arrows, encircled by the inscriptions E PLURIBUS UNUM, IN GOD WE TRUST, UNITED STATES OF AMERICA and 2 1/2 DOLLARS.'],
        'Gold $3' => ['copy' => 'This Indian Princess three-dollar gold piece was designed by James B. Longacre. His classic obverse depicts Liberty in a crown of feathers, on which is a band inscribed LIBERTY. Surrounding her is the inscription UNITED STATES OF AMERICA. The reverse features a wreath of corn, wheat, cotton and tobacco around 3 DOLLARS and the date of issue.',
            'alt1' => '', 'alt2' => ''],
        'Gold $5 Half Eagle' => ['copy' => 'This gold Classic Head half eagle was designed by William Kneass. Its obverse is based on John Reich\'s classic image of Liberty with flowing hair held by a band inscribed LIBERTY. The date is below, with 13 stars surrounding. The reverse depicts UNITED STATES OF AMERICA and 2 1/2 D. around an American eagle with Union shield, olive branch and three arrows.',
            'alt1' => 'This gold Liberty Head half eagle - also called a Coronet Head or Braided Hair half eagle - bears Christian Gobrecht\'s classic designs. The obverse depicts 13 stars around Liberty, who wears a diadem and her hair in a bun held by a string of beads. On the reverse, an American eagle with Union Shield holds an olive branch and three arrows. The denomination FIVE D. and UNITED STATES OF AMERICA encircle the reverse.', 'alt2' => 'This gold Liberty Head half eagle - also called a Coronet Head or Braided Hair half eagle - bears Christian Gobrecht\'s classic designs. The obverse depicts 13 stars around Liberty, who wears a diadem and her long hair in a bun held by a string of beads. On the reverse, an American eagle with Union Shield holds an olive branch and three arrows. Above the eagle is a banner with IN GOD WE TRUST, while UNITED STATES OF AMERICA and FIVE D. encircle the reverse.'],
        'Gold $10 Eagle' => ['copy' => 'This gold Liberty Head eagle - also called a Coronet Head or Braided Hair eagle - bears Christian Gobrecht\'s classic designs. The obverse shows 13 stars around Liberty, who wears a diadem and her long hair in a bun held by a string of beads. On the reverse, a proud American eagle with Union Shield holds an olive branch and three arrows. The denomination TEN D. and UNITED STATES OF AMERICA encircle the reverse.',
            'alt1' => 'This gold Liberty Head eagle - also called a Coronet Head or Braided Hair eagle - bears Christian Gobrecht\'s classic designs. The obverse depicts 13 stars around Liberty, who wears a diadem inscribed liberty. A string of beads holds her hair up in a bun. The reverse features an American eagle with Union Shield, an olive branch and three arrows. IN GOD WE TRUST appears on a banner above the eagle, with UNITED STATES OF AMERICA and FIVE D. encircling the design.', 'alt2' => 'This gold Indian Head eagle is one of America\'s most beautiful coins. Its obverse depicts Liberty crowned in a Native American war bonnet, with 13 stars above and the date below. On the reverse, an American perches atop a bundle of arrows and an olive branch. Surrounding the eagle are E PLURIBUS UNUM, UNITED STATES OF AMERICA and TEN DOLLARS. Along the edge are 46 stars - one for each state in the union when the coin was struck.'],
        'Gold $20 Double Eagle' => ['copy' => 'Struck in 90% gold over a century ago, this gold Liberty Head double eagle is larger than a Kennedy half dollar and weighs over 1 troy ounce. It bears James B. Longacre\'s classic design. The obverse shows Liberty in a diadem with her long hair up in a bun, surrounded by 13 stars and the date of issue. The reverse bears a stylish heraldic eagle beneath a circle of 13 stars and series of rays. The denomination and UNITED STATES OF AMERICA encircle the design.',
            'alt1' => '', 'alt2' => ''],
        'Fractional Pioneer Gold' => ['copy' => 'Struck during the California gold rush, this privately minted gold piece helped ease the shortage of small-denomination coins. Containing up to 85% of face value in real, California gold, these unique and historic issues quickly became collector favorites.',
            'alt1' => '', 'alt2' => ''],
        'Silver Bullion Coin' => ['copy' => 'Struck in 1 troy ounce of 99.9% pure silver, this hefty American silver eagle bears the series\' original designs. The obverse bears Adolph A. Weinman\'s beloved image of Liberty striding to greet the dawn of a new day. She wears a billowing gown of stars and stripes, and carries oak and laurel branches for military and civic glory. John Mercanti\'s striking reverse shows a heraldic eagle under a triangle of 13 stars. Encircling the reverse are UNITED STATES OF AMERICA and 1 OZ. FINE SILVER-ONE DOLLAR.',
            'alt1' => '', 'alt2' => ''],
        'Gold Bullion Coin' => ['copy' => 'This hefty $5 American Buffalo gold bullion coin contains 1/10 ounce of 99.99% pure gold. Only issued in 2008, it\'s from the first 24K gold coin series produced by the U.S. Mint. The coin bears James E. Fraser\'s iconic Buffalo nickel (or Indian Head) nickel designs. The obverse depicts a proud Native American, while the reverse shows an American bison.',
            'alt1' => 'This hefty $10 American Buffalo gold bullion coin contains 1/4 ounce of 99.99% pure gold. Only issued in 2008, it\'s from the first 24K gold coin series produced by the U.S. Mint. The coin bears James E. Fraser\'s iconic Buffalo nickel (or Indian Head) nickel designs. The obverse depicts a proud Native American, while the reverse shows an American bison.', 'alt2' => 'This hefty $25 American Buffalo gold bullion coin contains 1/2 ounce of 99.99% pure gold. Only issued in 2008, it\'s from the first 24K gold coin series produced by the U.S. Mint. The coin bears James E. Fraser\'s iconic Buffalo nickel (or Indian Head) nickel designs. The obverse depicts a proud Native American, while the reverse shows an American bison.'],
    ],
];
